import React, { useState, useMemo } from 'react';
import { Coltura, Meccanizzazione, CalculatorInputs, CalculatorResults } from '../types';

interface CalculatorProps {
  onResultGenerated: () => void;
}

// Static coefficients to avoid re-creation and potential undefined states
const ORE_PER_HA: Record<string, number> = {
  [Coltura.POMODORO]: 200,
  [Coltura.VIGNETO]: 400,
  [Coltura.OLIVO]: 600
};

const CORRETTIVO_MECC: Record<string, number> = {
  [Meccanizzazione.BASSA]: 1.2,
  [Meccanizzazione.MEDIA]: 1.0,
  [Meccanizzazione.ALTA]: 0.85
};

const BASE_TIME_TRAD: [number, number] = [12, 20];
const BASE_TIME_AVVIA: [number, number] = [5, 10];

const Calculator: React.FC<CalculatorProps> = ({ onResultGenerated }) => {
  const [inputs, setInputs] = useState<CalculatorInputs>({
    coltura: Coltura.POMODORO,
    ettari: 50,
    dataAvvio: new Date(Date.now() + 20 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    durataSettimane: 8,
    meccanizzazione: Meccanizzazione.MEDIA,
    giorniSettimana: 6,
    costoOperaio: 10.5,
    costoHR: 30,
    percPermesso: 30
  });

  const results = useMemo((): CalculatorResults => {
    const orePerHa = ORE_PER_HA[inputs.coltura] || 200;
    const correttivoMecc = CORRETTIVO_MECC[inputs.meccanizzazione] || 1.0;

    const oreTotali = inputs.ettari * orePerHa * correttivoMecc;
    const orePerPersona = inputs.durataSettimane * inputs.giorniSettimana * 8;
    const numeroStagionali = Math.max(1, Math.ceil(oreTotali / (orePerPersona || 1)));

    const costoManodopera = oreTotali * inputs.costoOperaio;

    const percPermessoDec = inputs.percPermesso / 100;

    // Scenario Tradizionale
    const tassoErroriTrad = 0.35;
    const oreHRPerCandidatoTrad = 2.2 + (0.9 * tassoErroriTrad) + (0.6 * percPermessoDec);
    const oreHRTotaliTrad = numeroStagionali * oreHRPerCandidatoTrad;
    const costoProcessoTrad = oreHRTotaliTrad * inputs.costoHR;

    // Scenario AvvIA
    const tassoErroriAvvia = 0.18;
    const oreHRPerCandidatoAvvia = 0.8 + (0.4 * tassoErroriAvvia) + (0.3 * percPermessoDec);
    const oreHRTotaliAvvia = numeroStagionali * oreHRPerCandidatoAvvia;
    const costoProcessoAvvia = oreHRTotaliAvvia * inputs.costoHR;

    const dateDiff = new Date(inputs.dataAvvio).getTime() - Date.now();
    const diffDays = Math.ceil(dateDiff / (1000 * 60 * 60 * 24));

    const penalty = 1 + (percPermessoDec * 0.5);
    const onboardingTrad: [number, number] = [
      Math.round(BASE_TIME_TRAD[0] * penalty),
      Math.round(BASE_TIME_TRAD[1] * penalty)
    ];
    const onboardingAvvia: [number, number] = [
      Math.round(BASE_TIME_AVVIA[0] * penalty),
      Math.round(BASE_TIME_AVVIA[1] * penalty)
    ];

    let rischio: 'Alto' | 'Medio' | 'Basso' = 'Basso';
    if (diffDays < 14) rischio = 'Alto';
    else if (diffDays < 21) rischio = 'Medio';

    return {
      oreTotali: Math.round(oreTotali),
      numeroStagionali,
      costoManodopera: Math.round(costoManodopera),
      costoProcessoTradizionale: Math.round(costoProcessoTrad),
      costoProcessoAvvIA: Math.round(costoProcessoAvvia),
      risparmioCosto: Math.round(costoProcessoTrad - costoProcessoAvvia),
      giorniOnboardingTradizionale: onboardingTrad,
      giorniOnboardingAvvia: onboardingAvvia,
      rischioRitardo: rischio,
      oreHRTradizionale: Math.round(oreHRTotaliTrad),
      oreHRAvvIA: Math.round(oreHRTotaliAvvia)
    };
  }, [inputs]);

  const diffDaysLabel = useMemo(() => {
    const d = Math.ceil((new Date(inputs.dataAvvio).getTime() - Date.now()) / (1000 * 60 * 60 * 24));
    return d > 0 ? `${d} giorni all'avvio` : 'Inizio imminente';
  }, [inputs.dataAvvio]);

  return (
    <div className="bg-white rounded-3xl shadow-2xl overflow-hidden border border-gray-100 flex flex-col lg:flex-row">
      {/* INPUTS PANEL */}
      <div className="lg:w-1/2 p-8 lg:p-12 border-b lg:border-b-0 lg:border-r border-gray-100 bg-[#FAF9F6]/50">
        <h3 className="text-xl font-semibold mb-8 flex items-center">
          <svg className="w-5 h-5 mr-2 text-teal-800" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" />
          </svg>
          Parametri Campagna
        </h3>

        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Coltura</label>
              <select 
                className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-teal-500 outline-none cursor-pointer"
                value={inputs.coltura}
                onChange={e => setInputs({...inputs, coltura: e.target.value as Coltura})}
              >
                {Object.values(Coltura).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Ettari Coltivati</label>
              <input 
                type="number" 
                className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-teal-500 outline-none"
                value={inputs.ettari}
                onChange={e => setInputs({...inputs, ettari: Math.max(0, parseInt(e.target.value) || 0)})}
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Inizio Campagna</label>
              <input 
                type="date" 
                className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-teal-500 outline-none"
                value={inputs.dataAvvio}
                onChange={e => setInputs({...inputs, dataAvvio: e.target.value})}
              />
              <p className="text-xs text-teal-700 mt-1 font-medium">{diffDaysLabel}</p>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Durata (settimane)</label>
              <input 
                type="number" 
                className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-teal-500 outline-none"
                value={inputs.durataSettimane}
                onChange={e => setInputs({...inputs, durataSettimane: Math.max(1, parseInt(e.target.value) || 0)})}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Meccanizzazione</label>
            <div className="grid grid-cols-3 gap-2">
              {Object.values(Meccanizzazione).map(m => (
                <button
                  key={m}
                  type="button"
                  onClick={() => setInputs({...inputs, meccanizzazione: m})}
                  className={`py-2 px-3 rounded-lg text-sm font-medium transition-all ${inputs.meccanizzazione === m ? 'bg-teal-800 text-white' : 'bg-white border border-gray-200 text-gray-600 hover:border-teal-200'}`}
                >
                  {m.charAt(0).toUpperCase() + m.slice(1)}
                </button>
              ))}
            </div>
            <p className="text-xs text-gray-500 mt-2 italic">Influenza il fabbisogno di manodopera stimato.</p>
          </div>

          <div className="pt-4 border-t border-gray-100">
            <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Dettagli Economici</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center group">
                  Costo Operaio (€/h)
                  <span className="ml-1 cursor-help text-gray-300 hover:text-gray-500" title="Costo orario lordo medio per operaio agricolo stagionale.">ⓘ</span>
                </label>
                <input 
                  type="number" 
                  step="0.1"
                  className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-teal-500 outline-none"
                  value={inputs.costoOperaio}
                  onChange={e => setInputs({...inputs, costoOperaio: parseFloat(e.target.value) || 0})}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Costo HR/Admin (€/h)</label>
                <input 
                  type="number" 
                  className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-teal-500 outline-none"
                  value={inputs.costoHR}
                  onChange={e => setInputs({...inputs, costoHR: parseFloat(e.target.value) || 0})}
                />
              </div>
            </div>
          </div>

          <div>
            <div className="flex justify-between items-center mb-1">
              <label className="block text-sm font-medium text-gray-700">% Permessi di Soggiorno</label>
              <span className="text-sm font-bold text-teal-800">{inputs.percPermesso}%</span>
            </div>
            <input 
              type="range" 
              className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-teal-800"
              min="0"
              max="100"
              value={inputs.percPermesso}
              onChange={e => setInputs({...inputs, percPermesso: parseInt(e.target.value)})}
            />
          </div>
        </div>
      </div>

      {/* OUTPUTS PANEL */}
      <div className="lg:w-1/2 p-8 lg:p-12 bg-white">
        <div className="flex justify-between items-start mb-10">
          <div>
            <h3 className="text-xl font-semibold text-gray-900">Output Simulazione</h3>
            <p className="text-sm text-gray-500">Stima basata su parametri reali di settore.</p>
          </div>
          <div className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-widest ${
            results.rischioRitardo === 'Alto' ? 'bg-red-100 text-red-700' : 
            results.rischioRitardo === 'Medio' ? 'bg-orange-100 text-orange-700' : 
            'bg-green-100 text-green-700'
          }`}>
            Rischio: {results.rischioRitardo || 'Basso'}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 mb-8">
          <div className="bg-[#FAF9F6] p-4 rounded-2xl border border-gray-50">
            <p className="text-xs text-gray-500 font-medium uppercase mb-1">Stagionali Stimati</p>
            <p className="text-3xl font-bold text-teal-900">{results.numeroStagionali || 0}</p>
