import React, { useState, useMemo } from 'react';
import { Coltura, Terreno, CalculatorInputs, CalculatorResults } from '../types';

// Coefficienti ore/uomo per ettaro (Tabelle regionali IT)
const ORE_PER_HA: Record<string, number> = {
  [Coltura.POMODORO]: 200,
  [Coltura.VIGNETO]: 400,
  [Coltura.OLIVO]: 600
};

// Fattori correttivi terreno
const FATTORE_TERRENO: Record<string, number> = {
  [Terreno.PIANURA]: 1.0,
  [Terreno.COLLINA]: 1.2,
  [Terreno.TERRAZZAMENTI]: 1.3
};

interface CalculatorProps {
  onResultGenerated: () => void;
}

const Calculator: React.FC<CalculatorProps> = ({ onResultGenerated }) => {
  const [showModal, setShowModal] = useState(false);
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [email, setEmail] = useState('');
  const [company, setCompany] = useState('');

  const [inputs, setInputs] = useState<CalculatorInputs>({
    coltura: Coltura.POMODORO,
    ettari: 20,
    dataAvvio: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    durataSettimane: 8,
    terreno: Terreno.PIANURA,
    percPermesso: 20,
    // Advanced defaults
    costoOperaio: 10.5,
    costoHR: 30,
    giorniSettimana: 6,
    oreGiorno: 8
  });

  const results = useMemo((): CalculatorResults => {
    const orePerHa = ORE_PER_HA[inputs.coltura] || 200;
    const fattoreTerreno = FATTORE_TERRENO[inputs.terreno] || 1.0;

    const oreTotali = inputs.ettari * orePerHa * fattoreTerreno;
    const orePersonaNelPeriodo = inputs.durataSettimane * inputs.giorniSettimana * inputs.oreGiorno;
    const numeroStagionali = Math.max(1, Math.ceil(oreTotali / (orePersonaNelPeriodo || 1)));

    const costoManodopera = oreTotali * inputs.costoOperaio;

    const pPermesso = inputs.percPermesso / 100;
    const pErroriDocManual = 0.35;
    const pErroriDocAvvia = 0.18;

    const oreHRPerCandidatoManuale = 1.7 + (1.0 * pErroriDocManual) + (0.8 * pPermesso);
    const oreHRPerCandidatoAvvia = 0.7 + (0.5 * pErroriDocAvvia) + (0.4 * pPermesso);

    const hManual = numeroStagionali * oreHRPerCandidatoManuale;
    const hAvvia = numeroStagionali * oreHRPerCandidatoAvvia;

    const daysDiff = Math.ceil((new Date(inputs.dataAvvio).getTime() - Date.now()) / (1000 * 60 * 60 * 24));
    const urgencyFactor = daysDiff < 15 ? 1.3 : 1.0;

    return {
      oreTotali: Math.round(oreTotali),
      numeroStagionali,
      costoManodopera: Math.round(costoManodopera),
      oreHRTradizionale: Math.round(hManual),
      oreHRAvvIA: Math.round(hAvvia),
      risparmioOre: Math.round(hManual - hAvvia),
      giorniOnboardingTradizionale: [Math.round(12 * urgencyFactor), Math.round(20 * urgencyFactor)],
      giorniOnboardingAvvIA: [Math.round(6 * urgencyFactor), Math.round(10 * urgencyFactor)]
    };
  }, [inputs]);

  const costoHRTradizionale = results.oreHRTradizionale * inputs.costoHR;
  const costoHRAvvIA = results.oreHRAvvIA * inputs.costoHR;
  const risparmioEuro = results.risparmioOre * inputs.costoHR;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSuccess(true);
      onResultGenerated();
    }, 1200);
  };

  return (
    <div className="relative">
      <div className="bg-white rounded-3xl shadow-2xl overflow-hidden border border-gray-100 flex flex-col lg:flex-row max-w-6xl mx-auto">
        {/* INPUT PANEL */}
        <div className="lg:w-2/5 p-8 lg:p-10 border-b lg:border-b-0 lg:border-r border-gray-100 bg-[#FAF9F6]/50">
          <h3 className="text-lg font-bold mb-6 text-gray-900 uppercase tracking-tight">Parametri Base</h3>

          <div className="space-y-5">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Coltura</label>
              <select 
                className="w-full bg-white border border-gray-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-teal-500 outline-none appearance-none cursor-pointer shadow-sm"
                value={inputs.coltura}
                onChange={e => setInputs({...inputs, coltura: e.target.value as Coltura})}
              >
                {Object.values(Coltura).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Ettari</label>
                <input 
                  type="number" 
                  className="w-full bg-white border border-gray-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-teal-500 outline-none shadow-sm"
                  value={inputs.ettari}
                  onChange={e => setInputs({...inputs, ettari: Math.max(1, parseInt(e.target.value) || 0)})}
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Durata (Sett.)</label>
                <input 
                  type="number" 
                  className="w-full bg-white border border-gray-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-teal-500 outline-none shadow-sm"
                  value={inputs.durataSettimane}
                  onChange={e => setInputs({...inputs, durataSettimane: Math.max(1, parseInt(e.target.value) || 0)})}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Inizio Campagna</label>
              <input 
                type="date" 
                className="w-full bg-white border border-gray-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-teal-500 outline-none shadow-sm"
                value={inputs.dataAvvio}
                onChange={e => setInputs({...inputs, dataAvvio: e.target.value})}
              />
            </div>

            <div className="pt-4 border-t border-gray-200">
              <button 
                onClick={() => setShowAdvanced(!showAdvanced)}
                className="text-sm font-medium text-teal-800 flex items-center hover:text-teal-900 transition-colors"
              >
                <svg className={`w-4 h-4 mr-2 transition-transform ${showAdvanced ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                </svg>
                Impostazioni avanzate
              </button>

              {showAdvanced && (
                <div className="mt-4 space-y-5 animate-fade-in">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Tipologia Terreno</label>
                    <select 
                      className="w-full bg-white border border-gray-200 rounded-xl px-3 py-2 text-sm outline-none"
                      value={inputs.terreno}
                      onChange={e => setInputs({...inputs, terreno: e.target.value as Terreno})}
                    >
                      {Object.values(Terreno).map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                  </div>
                  <div>
                    <div className="flex justify-between items-center mb-1">
                      <label className="text-xs font-medium text-gray-500">% con permesso di soggiorno</label>
                      <span className="text-xs font-bold text-teal-800">{inputs.percPermesso}%</span>
                    </div>
                    <input 
                      type="range" 
                      className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-teal-800"
                      min="0" max="100"
                      value={inputs.percPermesso}
                      onChange={e => setInputs({...inputs, percPermesso: parseInt(e.target.value)})}
                    />
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* OUTPUT PANEL */}
        <div className="lg:w-3/5 p-8 lg:p-12 bg-white flex flex-col justify-between">
          <div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
              <div className="bg-[#FAF9F6] p-6 rounded-3xl border border-gray-50">
                <p className="text-xs text-gray-500 font-bold uppercase tracking-widest mb-1">Stagionali Necessari</p>
                <p className="text-4xl font-extrabold text-teal-900">{results.numeroStagionali}</p>
                <p className="text-[10px] text-gray-400 mt-2 italic leading-tight">Basato su tabelle ore/uomo standard di settore.</p>
              </div>
              <div className="bg-[#FAF9F6] p-6 rounded-3xl border border-gray-50">
                <p className="text-xs text-gray-500 font-bold uppercase tracking-widest mb-1">Costo Lavoro Stimato</p>
                <p className="text-4xl font-extrabold text-teal-900">€{results.costoManodopera.toLocaleString()}</p>
                <p className="text-[10px] text-gray-400 mt-2 italic leading-tight">Esclusi costi amministrativi e contributi speciali.</p>
              </div>
            </div>

            <div className="pt-8 border-t border-gray-100">
              <div className="flex items-center justify-between mb-6">
                <h4 className="text-xl font-bold text-gray-900">Analisi Compliance & Risparmio</h4>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Traditional Value */}
                <div className="flex flex-col justify-between bg-gray-50 p-5 rounded-2xl border border-gray-100">
                  <span className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-3">Gestione Tradizionale</span>
                  <div>
                    <p className="text-lg font-bold text-gray-900">≈ {results.oreHRTradizionale} ore HR</p>
                    <p className="text-xl font-bold text-gray-400">€{costoHRTradizionale.toLocaleString()}</p>
                  </div>
                  <div className="mt-4 pt-4 border-t border-gray-200/60">
                    <span className="text-[10px] text-gray-400 font-bold uppercase block mb-1">Onboarding media</span>
                    <p className="text-xs font-semibold text-gray-600">{results.giorniOnboardingTradizionale[0]}-{results.giorniOnboardingTradizionale[1]} giorni</p>
                  </div>
                </div>

                {/* AvvIA Value */}
                <div className="flex flex-col justify-between bg-teal-50/50 p-5 rounded-2xl border border-teal-100">
                  <span className="text-xs font-bold text-teal-800 uppercase tracking-wider mb-3">Con AvvIA</span>
                  <div>
                    <p className="text-lg font-bold text-teal-900">≈ {results.oreHRAvvIA} ore HR</p>
                    <p className="text-xl font-bold text-teal-700">€{costoHRAvvIA.toLocaleString()}</p>
                  </div>
                  <div className="mt-4 pt-4 border-t border-teal-100/60">
                    <span className="text-[10px] text-teal-600 font-bold uppercase block mb-1">Onboarding media</span>
                    <p className="text-xs font-bold text-teal-800">{results.giorniOnboardingAvvIA[0]}-{results.giorniOnboardingAvvIA[1]} giorni</p>
                  </div>
                </div>
              </div>

              {/* Savings Highlight */}
              <div className="mt-6 text-center p-6 bg-teal-800 rounded-2xl shadow-lg animate-bounce-short">
                <p className="text-teal-100 text-sm font-medium uppercase tracking-widest mb-1">Risparmio stimato</p>
                <div className="flex items-center justify-center space-x-4">
                   <p className="text-white text-3xl font-extrabold">{results.risparmioOre} ore</p>
                   <div className="h-8 w-px bg-white/20"></div>
                   <p className="text-white text-3xl font-extrabold">€{risparmioEuro.toLocaleString()}</p>
                </div>
              </div>

              <p className="text-center text-[11px] text-gray-400 mt-4 leading-relaxed italic">
                “La maggior parte delle aziende agricole impiega il 25–40% del tempo HR in follow-up documentale.”
              </p>
            </div>
          </div>

          <div className="mt-10 text-center">
            <button 
              onClick={() => setShowModal(true)}
              className="w-full py-5 bg-teal-800 text-white rounded-2xl font-bold text-xl hover:bg-teal-900 transition-all shadow-2xl flex items-center justify-center group"
            >
              Scopri come AvvIA genera questo risparmio
              <svg className="w-5 h-5 ml-2 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
