                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  {inputs.filieraTrasformatore === FilieraTrasformatore.POMODORO && (
                    <div>
                      <label className="block text-sm font-bold text-gray-700 mb-2">Linee Attive</label>
                      <input 
                        type="number" 
